namespace MyApp.Eval;

internal static class EvalConstants
{
    /// <summary>
    /// Environment variable or config key for the Azure OpenAI endpoint used by evaluators.
    /// </summary>
    public const string EndpointEnvVar = "AZURE_OPENAI_ENDPOINT";

    /// <summary>
    /// The deployment name used for evaluation (judge model).
    /// </summary>
    public const string JudgeDeployment = "gpt-4o-mini";

    /// <summary>
    /// Directory where evaluation results are stored.
    /// </summary>
    public const string ResultsDir = ".eval-results";
}

using Azure.AI.OpenAI;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Eval;

/// <summary>
/// Shared setup for evaluation scenarios.
/// </summary>
internal static class EvalSetup
{
    public static IChatClient CreateJudgeChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable(EvalConstants.EndpointEnvVar)
            ?? throw new InvalidOperationException(
                $"Set {EvalConstants.EndpointEnvVar} to your Azure OpenAI endpoint.");

        var client = new AzureOpenAIClient(new Uri(endpoint), new DefaultAzureCredential());
        return client.GetChatClient(EvalConstants.JudgeDeployment).AsIChatClient();
    }

    public static ReportingConfiguration CreateReportingConfiguration(
        string scenarioName,
        params IEvaluator[] evaluators)
    {
        var storage = new DiskBasedReportingStorage(EvalConstants.ResultsDir);

        return new ReportingConfiguration(
            evaluators: evaluators,
            reportingStorage: storage,
            chatConfiguration: new ChatConfiguration(CreateJudgeChatClient()),
            scenarioName: scenarioName);
    }

    /// <summary>
    /// Standard quality evaluators for agentic responses.
    /// </summary>
    public static IEvaluator[] QualityEvaluators =>
    [
        new RelevanceEvaluator(),
        new CoherenceEvaluator(),
        new FluencyEvaluator(),
        new GroundednessEvaluator(),
    ];
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Telemetry mode: validates that the agent produces expected telemetry signals
/// (token usage, tool calls, latency) alongside correctness.
/// </summary>
[TestClass]
public class TelemetryEvalTests
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_config = EvalSetup.CreateReportingConfiguration(
            "Telemetry",
            EvalSetup.QualityEvaluators);
    }

    [TestMethod]
    public async Task Agent_ProducesValidTelemetry()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync("ProducesValidTelemetry");

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Summarize the benefits of unit testing in two sentences.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        // Validate telemetry: response must include usage metadata
        Assert.IsNotNull(response.Usage, "Response should include token usage telemetry.");
        Assert.IsTrue(response.Usage.InputTokenCount > 0, "Input tokens should be reported.");
        Assert.IsTrue(response.Usage.OutputTokenCount > 0, "Output tokens should be reported.");

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Agent_ResponseLatencyWithinBounds()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync("ResponseLatency");

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is dependency injection?")
        };

        var sw = System.Diagnostics.Stopwatch.StartNew();
        var response = await chatClient.GetResponseAsync(messages);
        sw.Stop();
        messages.Add(response.Message);

        // Telemetry: latency should be reasonable for a simple query
        Assert.IsTrue(sw.Elapsed < TimeSpan.FromSeconds(30),
            $"Response took {sw.Elapsed.TotalSeconds:F1}s which exceeds 30s threshold.");

        await scenario.EvaluateAsync(messages);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Quality mode: evaluates response quality using LLM-as-judge evaluators
/// (relevance, coherence, fluency, groundedness).
/// </summary>
[TestClass]
public class QualityEvalTests
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_config = EvalSetup.CreateReportingConfiguration(
            "Quality",
            EvalSetup.QualityEvaluators);
    }

    [TestMethod]
    public async Task Coach_ProvidesRelevantGuidance()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync("RelevantGuidance");

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant for software engineers."),
            new(ChatRole.User, "How can I improve the test coverage of my C# project?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        // All quality metrics should pass (score >= 3 out of 5)
        var results = scenario.GetEvaluationResult();
        AssertMetricAboveThreshold(results, RelevanceEvaluator.RelevanceMetricName, 3);
        AssertMetricAboveThreshold(results, CoherenceEvaluator.CoherenceMetricName, 3);
        AssertMetricAboveThreshold(results, FluencyEvaluator.FluencyMetricName, 3);
    }

    [TestMethod]
    public async Task Coach_GroundedInContext()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync("GroundedInContext");

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var context = """
            Our project uses xUnit for testing, has 45% line coverage,
            and the team wants to reach 80% coverage by next quarter.
            """;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, $"You are a coaching assistant. Context: {context}"),
            new(ChatRole.User, "What concrete steps should we take to hit our coverage goal?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages, additionalContext: [new EvaluationContext(context)]);

        var results = scenario.GetEvaluationResult();
        AssertMetricAboveThreshold(results, GroundednessEvaluator.GroundednessMetricName, 3);
    }

    private static void AssertMetricAboveThreshold(
        EvaluationResult results,
        string metricName,
        int threshold)
    {
        var metric = results.Metrics.First(m => m.Name == metricName) as NumericMetric;
        Assert.IsNotNull(metric, $"Metric '{metricName}' not found.");
        Assert.IsTrue(metric.Value >= threshold,
            $"Metric '{metricName}' scored {metric.Value}, expected >= {threshold}.");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Compare mode: runs the same prompts across two configurations and stores results
/// side-by-side so the reporting tool can diff them.
/// Use different scenario names (e.g., "Compare_Baseline" vs "Compare_Candidate") per run
/// and compare via the evaluation report viewer.
/// </summary>
[TestClass]
public class CompareEvalTests
{
    /// <summary>
    /// Set EVAL_VARIANT to "Baseline" or "Candidate" to tag the run.
    /// Defaults to "Baseline" if unset.
    /// </summary>
    private static string Variant =>
        Environment.GetEnvironmentVariable("EVAL_VARIANT") ?? "Baseline";

    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_config = EvalSetup.CreateReportingConfiguration(
            $"Compare_{Variant}",
            EvalSetup.QualityEvaluators);
    }

    [TestMethod]
    public async Task Compare_CoachingResponse()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync("CoachingResponse");

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a coaching assistant for software teams."),
            new(ChatRole.User, "Our deployments keep failing on Friday afternoons. What should we change?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        // Record metrics for comparison; threshold enforcement is optional in compare mode.
        var results = scenario.GetEvaluationResult();
        Assert.IsTrue(results.Metrics.Any(), "Expected at least one metric result.");
    }

    [TestMethod]
    public async Task Compare_TechnicalExplanation()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync("TechnicalExplanation");

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a coaching assistant for software teams."),
            new(ChatRole.User, "Explain the difference between integration tests and end-to-end tests.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        var results = scenario.GetEvaluationResult();
        Assert.IsTrue(results.Metrics.Any(), "Expected at least one metric result.");
    }
}

