/// (token usage, tool calls, latency) alongside correctness.
/// </summary>
[TestClass]
public class TelemetryEvalTests
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_config = EvalSetup.CreateReportingConfiguration(
            "Telemetry",
            EvalSetup.QualityEvaluators);
    }

    [TestMethod]
    public async Task Agent_ProducesValidTelemetry()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync("ProducesValidTelemetry");

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Summarize the benefits of unit testing in two sentences.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        // Validate telemetry: response must include usage metadata
        Assert.IsNotNull(response.Usage, "Response should include token usage telemetry.");
        Assert.IsTrue(response.Usage.InputTokenCount > 0, "Input tokens should be reported.");
        Assert.IsTrue(response.Usage.OutputTokenCount > 0, "Output tokens should be reported.");

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Agent_ResponseLatencyWithinBounds()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync("ResponseLatency");

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is dependency injection?")
        };

        var sw = System.Diagnostics.Stopwatch.StartNew();
        var response = await chatClient.GetResponseAsync(messages);
        sw.Stop();
        messages.Add(response.Message);

        // Telemetry: latency should be reasonable for a simple query
        Assert.IsTrue(sw.Elapsed < TimeSpan.FromSeconds(30),
            $"Response took {sw.Elapsed.TotalSeconds:F1}s which exceeds 30s threshold.");

        await scenario.EvaluateAsync(messages);
    }
}

